n":"charged power bank","kk":"зарядталған қуаттағыш"}},{"itemType":"CASH","title":{"ru":"Карта/наличные","en":"Card or cash","kk":"Қолма-қол ақша"},"importance":"RECOMMENDED","sortOrder":40,"note":{"ru":"офлайн-карта","en":"card or cash","kk":"қолма-қол ақша немесе карта"}},{"itemType":"RAIN","title":{"ru":"Дождевик","en":"Rain jacket","kk":"Жаңбырлық"},"importance":"RECOMMENDED","sortOrder":50,"note":{"ru":"дождевик","en":"rain protection","kk":"жаңбырдан қорғаныс"}},{"itemType":"WARM_CLOTHES","title":{"ru":"Тёплая одежда","en":"Warm layer","kk":"Жылы қабат"},"importance":"RECOMMENDED","sortOrder":60,"note":{"ru":"ветровка","en":"warm layer","kk":"жылы қабат"}}]}$$::jsonb);


DO $$
BEGIN
    IF EXISTS (
        WITH candidate_matches AS (
            SELECT
                seed.title_ru,
                COUNT(DISTINCT p.id) AS match_count
            FROM seed_tajikistan_visit_planning seed
            LEFT JOIN place_translations pt
              ON pt.locale = 'ru'
             AND pt.title = seed.title_ru
            LEFT JOIN places p
              ON p.id = pt.place_id
             AND p.country_code = 'TJ'
             AND p.deleted_at IS NULL
             AND p.source = 'IMPORT'
            GROUP BY seed.title_ru
        )
        SELECT 1
        FROM candidate_matches
        WHERE match_count <> 1
    ) THEN
        RAISE EXCEPTION 'Tajikistan visit-planning seed has missing or ambiguous place matches';
    END IF;
END $$;

WITH matched_places AS (
    SELECT DISTINCT
        p.id AS place_id,
        seed.price_amount,
        seed.visit_info
    FROM seed_tajikistan_visit_planning seed
    JOIN place_translations pt
      ON pt.locale = 'ru'
     AND pt.title = seed.title_ru
    JOIN places p
      ON p.id = pt.place_id
     AND p.country_code = 'TJ'
     AND p.deleted_at IS NULL
     AND p.source = 'IMPORT'
)
DELETE FROM place_fee_items f
USING matched_places m
WHERE f.place_id = m.place_id;

WITH matched_places AS (
    SELECT DISTINCT
        p.id AS place_id,
        seed.price_amount,
        seed.visit_info
    FROM seed_tajikistan_visit_planning seed
    JOIN place_translations pt
      ON pt.locale = 'ru'
     AND pt.title = seed.title_ru
    JOIN places p
      ON p.id = pt.place_id
     AND p.country_code = 'TJ'
     AND p.deleted_at IS NULL
     AND p.source = 'IMPORT'
)
DELETE FROM place_access_options a
USING matched_places m
WHERE a.place_id = m.place_id;

